-- 25 launch examples across different specialties. They are visibly labeled as examples
-- and cannot receive applications until replaced with real employer postings.
values ('gortsak-launch-examples', 'Գործակ մեկնարկային օրինակներ', 'launch-examples@gortsak.invalid', 'employer', 'Հարթակի մեկնարկային հայտարարությունների օրինակային հաշիվ։')
on conflict (user_id) do update set display_name=excluded.display_name, role='employer';

on conflict (id) do nothing;
